"use client";

/**
 * App Store preview film, vertical: a title that rides in on a wave, the app
 * on a phone, a plan picker that spins and lands, a message thread where
 * people share the app, then the logo reveal. About 20 seconds at 1080 by
 * 1920, the App Store's accepted size for 16:9 iPhones. iPhones with Face ID
 * or Dynamic Island take 886 by 1920; App Store Connect scales a preview that
 * does not match. Every scene is a Better Design video component, cut together with
 * the whip pan transition. Scenes laid out for a wide frame are set on a
 * taller canvas and scaled to the phone width, so nothing is cropped.
 *
 * Written by Better Design.
 */
import { linearTiming, TransitionSeries } from "@remotion/transitions";
import type { ReactNode } from "react";
import { AbsoluteFill, Easing } from "remotion";
import { LetterWave } from "@/components/bd-video/letter-wave";
import { LogoReveal } from "@/components/bd-video/logo-reveal";
import { MessageBubbles } from "@/components/bd-video/message-bubbles";
import { PhoneMockup } from "@/components/bd-video/phone-mockup";
import { PickerSpin } from "@/components/bd-video/picker-spin";
import { whipPan } from "@/components/bd-video/transition-whip-pan";
import { type VideoTheme, VideoThemeProvider } from "@/lib/bd-video";

/** Every piece of copy and picture the App Store preview film shows. */
export interface AppStorePreviewFilmContent {
  /** The opening title. Short titles read best. */
  hook: string;
  /** Screen recording (.mp4, .webm, .mov) or a still for the phone. A placeholder app is drawn when unset. */
  screen?: string;
  /** The rows on the plan picker, and the index of the one it lands on. */
  options: string[];
  selected: number;
  /** One line above the picker. */
  pickerCaption: string;
  /** The thread after the shared link. Each entry starts with "me:" or "them:". */
  messages: string[];
  /** The person on the other side of the thread. */
  contact: string;
  /** Title and address on the shared link preview. */
  linkTitle: string;
  linkUrl: string;
  /** Poster picture for the link preview. A drawn frame stands in when unset. */
  linkPoster?: string;
  /** The app name in the closing lockup. */
  name: string;
  /** Image path for the app icon. Unset, the name's initials sit on a primary tile. */
  icon?: string;
  /** Pictures that fold into the icon. Unset, gradient tiles stand in. */
  pictures: string[];
}

const DEFAULT_CONTENT: AppStorePreviewFilmContent = {
  hook: "Plan your week in a minute",
  options: ["Free", "Starter", "Plus", "Pro", "Team", "Business", "Scale"],
  selected: 3,
  pickerCaption: "Choose your plan",
  messages: ["me: Have you tried this app?", "them: Just downloaded it", "them: My week is sorted already", "me: Told you"],
  contact: "Alex",
  linkTitle: "Your app on the App Store",
  linkUrl: "apps.apple.com/your-app",
  name: "Your app",
  pictures: [],
};

export interface AppStorePreviewFilmProps {
  content?: Partial<AppStorePreviewFilmContent>;
  theme?: Partial<VideoTheme>;
}

const WIDTH = 1080;
const HEIGHT = 1920;

/**
 * Lays a scene out on a canvas `1 / scale` times the frame, then scales it
 * back down. A scene built for 1920 wide gets room to breathe and still
 * fills the phone frame top to bottom.
 */
function Fit({ scale, children }: { scale: number; children: ReactNode }) {
  return (
    <AbsoluteFill style={{ overflow: "hidden" }}>
      <div style={{ position: "absolute", left: 0, top: 0, width: WIDTH / scale, height: HEIGHT / scale, transform: `scale(${scale})`, transformOrigin: "0 0" }}>
        <AbsoluteFill>{children}</AbsoluteFill>
      </div>
    </AbsoluteFill>
  );
}

/** Frames per scene, in order: hook, phone, picker, messages, logo. */
const SCENES = [120, 120, 120, 180, 130] as const;
const CUT = 15;
const cut = () => <TransitionSeries.Transition presentation={whipPan({ direction: "left" })} timing={linearTiming({ durationInFrames: CUT, easing: Easing.bezier(0.7, 0, 0.3, 1) })} />;

/** A vertical App Store preview film built from Better Design video components. */
export function AppStorePreviewFilm({ content, theme }: AppStorePreviewFilmProps) {
  const c = { ...DEFAULT_CONTENT, ...content };
  // The lockup sets the name at a fixed size, so a longer name gets a wider canvas.
  const logoScale = Math.min(1.2, 11 / Math.max(1, c.name.length));
  return (
    <VideoThemeProvider theme={theme}>
      <TransitionSeries>
        <TransitionSeries.Sequence durationInFrames={SCENES[0]}>
          <Fit scale={1.35}>
            <LetterWave text={c.hook} lead={1} theme={theme} />
          </Fit>
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[1]}>
          <Fit scale={1.6}>
            <PhoneMockup src={c.screen} tilt={8} caption="" theme={theme} />
          </Fit>
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[2]}>
          <Fit scale={1.25}>
            <PickerSpin options={c.options} selected={c.selected} caption={c.pickerCaption} theme={theme} />
          </Fit>
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[3]}>
          <Fit scale={1.5}>
            <MessageBubbles messages={c.messages} contact={c.contact} videoTitle={c.linkTitle} videoUrl={c.linkUrl} poster={c.linkPoster} theme={theme} />
          </Fit>
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[4]}>
          <Fit scale={logoScale}>
            <LogoReveal name={c.name} mark={c.icon} pictures={c.pictures} variant="stack" theme={theme} />
          </Fit>
        </TransitionSeries.Sequence>
      </TransitionSeries>
    </VideoThemeProvider>
  );
}

/** Composition settings. The duration is the scenes minus the four 15-frame cuts. */
export const APP_STORE_PREVIEW_FILM = { durationInFrames: 610, fps: 30, width: 1080, height: 1920 } as const;
